class Solution {
    public java.util.List<Double> averageOfLevels(TreeNode root) {
        java.util.List<Double> averages = new java.util.ArrayList<>();
        java.util.ArrayDeque<TreeNode> queue = new java.util.ArrayDeque<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            double sum = 0.0;
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.removeFirst();
                sum += (double) node.val;
                if (node.left != null) {
                    queue.addLast(node.left);
                }
                if (node.right != null) {
                    queue.addLast(node.right);
                }
            }
            averages.add(sum / levelSize);
        }
        return averages;
    }
}

class Solution {
    public java.util.List<Double> averageOfLevels(TreeNode root) {
        java.util.List<Double> sums = new java.util.ArrayList<>();
        java.util.List<Integer> counts = new java.util.ArrayList<>();
        collect(root, 0, sums, counts);

        java.util.List<Double> averages = new java.util.ArrayList<>();
        for (int level = 0; level < sums.size(); level++) {
            averages.add(sums.get(level) / counts.get(level));
        }
        return averages;
    }

    private void collect(TreeNode node, int depth, java.util.List<Double> sums, java.util.List<Integer> counts) {
        if (node == null) {
            return;
        }
        if (depth == sums.size()) {
            sums.add(0.0);
            counts.add(0);
        }
        sums.set(depth, sums.get(depth) + (double) node.val);
        counts.set(depth, counts.get(depth) + 1);
        collect(node.left, depth + 1, sums, counts);
        collect(node.right, depth + 1, sums, counts);
    }
}

class Solution {
    public java.util.List<Double> averageOfLevels(TreeNode root) {
        java.util.List<Double> sums = new java.util.ArrayList<>();
        java.util.List<Integer> counts = new java.util.ArrayList<>();
        java.util.ArrayDeque<TreeNode> nodes = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> depths = new java.util.ArrayDeque<>();
        nodes.push(root);
        depths.push(0);

        while (!nodes.isEmpty()) {
            TreeNode node = nodes.pop();
            int depth = depths.pop();
            if (depth == sums.size()) {
                sums.add(0.0);
                counts.add(0);
            }
            sums.set(depth, sums.get(depth) + (double) node.val);
            counts.set(depth, counts.get(depth) + 1);

            if (node.right != null) {
                nodes.push(node.right);
                depths.push(depth + 1);
            }
            if (node.left != null) {
                nodes.push(node.left);
                depths.push(depth + 1);
            }
        }

        for (int level = 0; level < sums.size(); level++) {
            sums.set(level, sums.get(level) / counts.get(level));
        }
        return sums;
    }
}
